'use strict';
// Preserve route IDs and all existing editors while replacing only navigation.
const groupedRender=render;
function horizontalNavigation(){const brand=$('.brand span:last-child');if(brand)brand.textContent='Xưởng Nội Dung';const current=view==='calendar'?'publish':view;$('#nav').innerHTML=navGroups.map(([label,items],i)=>{const active=items.includes(current);return `<details class="top-group ${active?'is-active':''}"><summary>${label}<span class="chevron" aria-hidden="true">⌄</span></summary><div class="top-dropdown">${items.map(k=>`<a href="#${k}" ${current===k?'aria-current="page"':''} class="${current===k?'active':''}">${icon(k)}${navs[k]}</a>`).join('')}</div></details>`}).join('');const backup=$('#backupSide');if(backup&&backup.parentElement!==$('header'))$('header').append(backup);let version=$('#appVersion');if(!version){version=document.createElement('span');version.id='appVersion';$('footer').prepend(version)}version.textContent='Xưởng 0.5.0';}
render=function(){groupedRender();horizontalNavigation()};
document.addEventListener('click',e=>{const summary=e.target.closest('.top-group summary');if(summary){const own=summary.parentElement;document.querySelectorAll('.top-group[open]').forEach(d=>{if(d!==own)d.open=false})}else if(!e.target.closest('.top-group'))document.querySelectorAll('.top-group[open]').forEach(d=>d.open=false);if(e.target.closest('.top-dropdown a'))document.querySelectorAll('.top-group[open]').forEach(d=>d.open=false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('.top-group[open]');if(open){open.open=false;open.querySelector('summary').focus()}}});
horizontalNavigation();
